package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import android.provider.*;import android.provider.ContactsContract.CommonDataKinds.*;import android.telephony.PhoneNumberUtils;import android.util.Base64;import org.json.*;import java.io.*;import java.util.*;

/** Additive personal archive. Fixed provider fields, exact duplicate detection, no transmission. */
final class PeopleArchive {
 static final int CONTACTS=500,SMS=2000;
 static String phone(String value){return PhoneNumberUtils.normalizeNumber(value==null?"":value);}
 static String contactKey(JSONObject row)throws Exception{TreeSet<String> numbers=new TreeSet<String>();JSONArray a=row.getJSONArray("numbers");for(int i=0;i<a.length();i++)numbers.add(phone(a.getJSONObject(i).getString("number")));return BackupEngine.hash((row.getString("name").trim().toLowerCase(Locale.ROOT)+"|"+numbers.toString()).getBytes("UTF-8"));}
 static String smsKey(JSONObject row)throws Exception{return BackupEngine.hash((phone(row.getString("address"))+"|"+row.getLong("stamp")+"|"+row.getInt("sub")+"|"+(row.getInt("type")==1?"in":"out")+"|"+row.getString("body")).getBytes("UTF-8"));}
 static JSONObject snapshot(Context c,boolean contacts,boolean sms)throws Exception{JSONObject data=new JSONObject();data.put("contacts",contacts?contacts(c,true):new JSONArray());data.put("sms",sms?messages(c):new JSONArray());validate(data);return data;}
 static JSONArray contacts(Context c,boolean photos)throws Exception{JSONArray out=new JSONArray();try(Cursor rows=c.getContentResolver().query(ContactsContract.Contacts.CONTENT_URI,new String[]{"_id","display_name","starred","photo_uri"},ContactsContract.Contacts.HAS_PHONE_NUMBER+"=1",null,"_id ASC")){while(rows!=null&&rows.moveToNext()){if(out.length()>=CONTACTS)throw new IOException(L.t("Agenda depășește 500 de contacte; folosește VCF"));JSONObject row=new JSONObject().put("name",rows.getString(1)==null?L.t("Fără nume"):rows.getString(1)).put("favorite",rows.getInt(2)!=0);JSONArray nums=new JSONArray();try(Cursor phones=c.getContentResolver().query(Phone.CONTENT_URI,new String[]{Phone.NUMBER,Phone.TYPE,Phone.LABEL},Phone.CONTACT_ID+"=?",new String[]{""+rows.getLong(0)},null)){while(phones!=null&&phones.moveToNext())nums.put(new JSONObject().put("number",phones.getString(0)).put("type",phones.getInt(1)).put("label",phones.getString(2)==null?"":phones.getString(2)));}row.put("numbers",nums);if(photos&&rows.getString(3)!=null){android.graphics.Bitmap b=Appearance.decode(c,android.net.Uri.parse(rows.getString(3)),192);try{ByteArrayOutputStream bytes=new ByteArrayOutputStream();b.compress(android.graphics.Bitmap.CompressFormat.JPEG,80,bytes);row.put("photo",Base64.encodeToString(bytes.toByteArray(),Base64.NO_WRAP));}finally{b.recycle();}}out.put(row);}}return out;}
 static JSONObject message(String address,String body,long date,long sent,int sub,int type,int delivery)throws Exception{return new JSONObject().put("address",address).put("body",body).put("date",date).put("stamp",sent>0?sent:date).put("sub",sub).put("type",type).put("delivery",delivery);}
 static void addMessage(JSONArray all,Set<String> seen,JSONObject row)throws Exception{if(seen.add(smsKey(row))){if(all.length()>=SMS)throw new IOException(L.t("Arhiva depășește 2000 de SMS-uri"));all.put(row);}}
 static JSONArray messages(Context c)throws Exception{JSONArray all=new JSONArray();Set<String> seen=new HashSet<String>();try(Cursor rows=c.getContentResolver().query(Telephony.Sms.CONTENT_URI,new String[]{"address","body","date","date_sent","sub_id","type"},"type<>3",null,"date ASC")){while(rows!=null&&rows.moveToNext()){if(rows.getString(0)==null||rows.getString(1)==null)continue;addMessage(all,seen,message(rows.getString(0),rows.getString(1),rows.getLong(2),rows.getLong(3),rows.getInt(4),rows.getInt(5),-1));}}try(SmsStore store=new SmsStore(c)){try(Cursor row=store.getReadableDatabase().query("inbox",null,null,null,null,null,"date ASC")){while(row.moveToNext())addMessage(all,seen,message(row.getString(row.getColumnIndexOrThrow("address")),row.getString(row.getColumnIndexOrThrow("body")),row.getLong(row.getColumnIndexOrThrow("date")),row.getLong(row.getColumnIndexOrThrow("sent")),row.getInt(row.getColumnIndexOrThrow("sub")),1,-1));}try(Cursor row=store.getReadableDatabase().query("outgoing",null,null,null,null,null,"date ASC")){while(row.moveToNext())addMessage(all,seen,message(row.getString(row.getColumnIndexOrThrow("address")),row.getString(row.getColumnIndexOrThrow("body")),row.getLong(row.getColumnIndexOrThrow("date")),row.getLong(row.getColumnIndexOrThrow("archive_stamp")),row.getInt(row.getColumnIndexOrThrow("sub")),row.getInt(row.getColumnIndexOrThrow("type")),row.getInt(row.getColumnIndexOrThrow("delivery"))));}}return all;}
 static void validate(JSONObject d)throws Exception{JSONArray contacts=d.getJSONArray("contacts"),sms=d.getJSONArray("sms");if(contacts.length()>CONTACTS||sms.length()>SMS)throw new IOException(L.t("Prea multe înregistrări"));for(int i=0;i<contacts.length();i++){JSONObject r=contacts.getJSONObject(i);if(r.getString("name").isEmpty()||r.getString("name").length()>512)throw new IOException(L.t("Nume invalid"));r.getBoolean("favorite");JSONArray nums=r.getJSONArray("numbers");if(nums.length()<1||nums.length()>10)throw new IOException(L.t("Contact cu 1–10 numere necesar"));for(int n=0;n<nums.length();n++){JSONObject p=nums.getJSONObject(n);if(!ContactBook.valid(p.getString("number"))||p.getInt("type")<0||p.getInt("type")>20||p.getString("label").length()>128)throw new IOException(L.t("Număr invalid"));}if(r.has("photo")){byte[] b=Base64.decode(r.getString("photo"),Base64.DEFAULT);android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeByteArray(b,0,b.length,o);if(b.length>131072||o.outWidth<1||o.outHeight<1||o.outWidth>512||o.outHeight>512)throw new IOException(L.t("Fotografie invalidă"));}}
  for(int i=0;i<sms.length();i++){JSONObject r=sms.getJSONObject(i);int type=r.getInt("type"),delivery=r.getInt("delivery");if(r.getString("address").isEmpty()||r.getString("address").length()>128||r.getString("body").length()>16384||r.getLong("date")<0||r.getLong("stamp")<0||type<1||type>6||type==3||delivery< -1||delivery>3)throw new IOException(L.t("SMS invalid"));r.getInt("sub");}}
 static byte[] archive(JSONObject data)throws Exception{validate(data);String payload=data.toString();byte[] bytes=new JSONObject().put("format","leo-people").put("version",1).put("sha256",BackupEngine.hash(payload.getBytes("UTF-8"))).put("payload",payload).toString().getBytes("UTF-8");if(bytes.length>BackupEngine.MAX)throw new IOException(L.t("Arhiva depășește 8 MiB"));return bytes;}
 static JSONObject read(File file)throws Exception{JSONObject a=new JSONObject(new String(BackupEngine.atomicBytes(file,BackupEngine.MAX),"UTF-8"));if(!"leo-people".equals(a.getString("format"))||a.getInt("version")!=1)throw new IOException(L.t("Format necunoscut"));String p=a.getString("payload");if(!BackupEngine.hash(p.getBytes("UTF-8")).equals(a.getString("sha256")))throw new IOException(L.t("Fișier deteriorat"));JSONObject d=new JSONObject(p);validate(d);return d;}
 static File export(Context c,File folder,boolean contacts,boolean sms)throws Exception{if(!folder.isDirectory()&&!folder.mkdirs())throw new IOException(L.t("Folder indisponibil"));File file=new File(folder,"leo-people-"+System.currentTimeMillis()+"-"+UUID.randomUUID().toString().substring(0,8)+".leo-people.json");BackupEngine.write(file,archive(snapshot(c,contacts,sms)));return file;}
 static int[] plan(Context c,JSONObject data,boolean useContacts,boolean useSms)throws Exception{validate(data);Set<String> ck=new HashSet<String>(),mk=new HashSet<String>();if(useContacts){JSONArray existing=contacts(c,false);for(int i=0;i<existing.length();i++)ck.add(contactKey(existing.getJSONObject(i)));}if(useSms){JSONArray existing=messages(c);for(int i=0;i<existing.length();i++)mk.add(smsKey(existing.getJSONObject(i)));}int[] result=new int[4];for(int group=0;group<2;group++){if(group==0&&!useContacts||group==1&&!useSms)continue;JSONArray a=data.getJSONArray(group==0?"contacts":"sms");for(int i=0;i<a.length();i++){JSONObject row=a.getJSONObject(i);boolean add=(group==0?ck:mk).add(group==0?contactKey(row):smsKey(row));result[group*2+(add?0:1)]++;}}return result;}
 static int[] merge(Context c,JSONObject data,boolean useContacts,boolean useSms)throws Exception{validate(data);int[] count=new int[4];Set<String> keys=new HashSet<String>();if(useContacts){JSONArray existing=contacts(c,false);for(int i=0;i<existing.length();i++)keys.add(contactKey(existing.getJSONObject(i)));JSONArray all=data.getJSONArray("contacts");for(int i=0;i<all.length();i++){JSONObject row=all.getJSONObject(i);String key=contactKey(row);if(!keys.add(key)){count[1]++;continue;}ArrayList<ContentProviderOperation> ops=new ArrayList<ContentProviderOperation>();ops.add(ContentProviderOperation.newInsert(ContactsContract.RawContacts.CONTENT_URI).withValue("account_type",null).withValue("account_name",null).withValue("starred",row.getBoolean("favorite")?1:0).build());ops.add(ContentProviderOperation.newInsert(ContactsContract.Data.CONTENT_URI).withValueBackReference("raw_contact_id",0).withValue("mimetype",StructuredName.CONTENT_ITEM_TYPE).withValue(StructuredName.DISPLAY_NAME,row.getString("name")).build());JSONArray nums=row.getJSONArray("numbers");for(int n=0;n<nums.length();n++){JSONObject p=nums.getJSONObject(n);ops.add(ContentProviderOperation.newInsert(ContactsContract.Data.CONTENT_URI).withValueBackReference("raw_contact_id",0).withValue("mimetype",Phone.CONTENT_ITEM_TYPE).withValue(Phone.NUMBER,p.getString("number")).withValue(Phone.TYPE,p.getInt("type")).withValue(Phone.LABEL,p.getString("label")).build());}if(row.has("photo"))ops.add(ContentProviderOperation.newInsert(ContactsContract.Data.CONTENT_URI).withValueBackReference("raw_contact_id",0).withValue("mimetype",Photo.CONTENT_ITEM_TYPE).withValue(Photo.PHOTO,Base64.decode(row.getString("photo"),Base64.DEFAULT)).build());c.getContentResolver().applyBatch(ContactsContract.AUTHORITY,ops);count[0]++;}}
  if(useSms){keys.clear();JSONArray existing=messages(c);for(int i=0;i<existing.length();i++)keys.add(smsKey(existing.getJSONObject(i)));try(SmsStore store=new SmsStore(c)){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{JSONArray all=data.getJSONArray("sms");for(int i=0;i<all.length();i++){JSONObject row=all.getJSONObject(i);String key=smsKey(row);if(!keys.add(key)){count[3]++;continue;}boolean in=row.getInt("type")==1;ContentValues v=new ContentValues();v.put(in?"hash":"token","backup:"+key);v.put("address",row.getString("address"));v.put("body",row.getString("body"));v.put("date",row.getLong("date"));v.put("sub",row.getInt("sub"));if(in){v.put("sent",row.getLong("stamp"));v.put("unread",0);}else{v.put("type",row.getInt("type")==2?2:5);v.put("delivery",row.getInt("delivery"));v.put("archive_stamp",row.getLong("stamp"));}db.insertOrThrow(in?"inbox":"outgoing",null,v);count[2]++;}db.setTransactionSuccessful();}finally{db.endTransaction();}}}UnreadState.refresh(c);return count;}
}
